package oracle

import (
	"chain"
	"chain/runtime"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/amm/v1"
	"gno.land/r/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/v2"
)

const (
	ringCap      = 32
	scaleX6      = int64(1_000_000)
	dexPkg       = "gno.land/r/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/v2"
	protoVersion = "1"
)

type Sample struct {
	H  int64
	Px int64
}

type Ring struct {
	Items []Sample
}

var rings avl.Tree // poolID -> *Ring

func Version() string { return protoVersion }
func DexPkg() string  { return dexPkg }

func height() int64 { return runtime.ChainHeight() }

func require(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

func getRing(poolID string) *Ring {
	if v := rings.Get(poolID); v != nil {
		return v.(*Ring)
	}
	r := &Ring{}
	rings.Set(poolID, r)
	return r
}

// Ping stores SpotPrice for poolID. Same height overwrites last. Ring drops oldest at 32.
func Ping(cur realm, poolID string) int64 {
	require(cur.Previous().IsUserCall(), "zdex: EOA-only")
	ru, rt, vu, _, _ := zdex.PoolInfo(poolID)
	den := ru + vu
	require(den > 0 && rt > 0, "zdex: empty pool")
	px := amm.MulDiv(rt, scaleX6, den)
	h := height()
	r := getRing(poolID)
	n := len(r.Items)
	if n > 0 && r.Items[n-1].H == h {
		r.Items[n-1].Px = px
		chain.Emit("Ping", "pool", poolID, "px", itoa(px), "h", itoa(h))
		return px
	}
	if n >= ringCap {
		r.Items = r.Items[1:]
	}
	r.Items = append(r.Items, Sample{H: h, Px: px})
	chain.Emit("Ping", "pool", poolID, "px", itoa(px), "h", itoa(h))
	return px
}

// Observe is TWAP of stored spots over [now-agoBlocks, now]. Panics if the window is thin.
func Observe(poolID string, agoBlocks int64) int64 {
	require(agoBlocks > 0, "zdex: window")
	r := getRing(poolID)
	require(len(r.Items) >= 2, "zdex: thin window")
	now := height()
	target := now - agoBlocks
	if r.Items[0].H > target {
		panic("zdex: thin window")
	}
	num, den := int64(0), int64(0)
	for i, s := range r.Items {
		from := s.H
		to := now
		if i+1 < len(r.Items) {
			to = r.Items[i+1].H
		}
		if to <= target {
			continue
		}
		if from < target {
			from = target
		}
		if to > now {
			to = now
		}
		dt := to - from
		if dt <= 0 {
			continue
		}
		add, ok := mul(s.Px, dt)
		if !ok {
			chain.Emit("ObserveSkip", "pool", poolID)
			continue
		}
		num, ok = add64(num, add)
		if !ok {
			chain.Emit("ObserveSkip", "pool", poolID)
			continue
		}
		den += dt
	}
	require(den > 0, "zdex: thin window")
	return num / den
}

func SampleCount(poolID string) int {
	if v := rings.Get(poolID); v != nil {
		return len(v.(*Ring).Items)
	}
	return 0
}

func LastSpot(poolID string) int64 {
	r := getRing(poolID)
	n := len(r.Items)
	if n == 0 {
		return 0
	}
	return r.Items[n-1].Px
}

func add64(a, b int64) (int64, bool) {
	s := a + b
	if (b > 0 && s < a) || (b < 0 && s > a) {
		return 0, false
	}
	return s, true
}

func mul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	p := a * b
	if a != 0 && p/a != b {
		return 0, false
	}
	return p, true
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

package incentives

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/amm/v1"
	"gno.land/r/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/v2"
)

func takeFund(cur realm, poolID string) (sent int64, g *Gauge) {
	require(cur.Previous().IsUserCall(), "zdex: ugnot is EOA-only")
	require(!paused, "zdex: paused")
	os := unsafe.OriginSend()
	require(len(os) == 1 && os[0].Denom == nativeDenom, "zdex: only ugnot")
	sent = os.AmountOf(nativeDenom)
	require(sent >= minFundUgnot, "zdex: min 1 GNOT")
	_, _, _, totalLP, _ := zdex.PoolInfo(poolID)
	require(totalLP > minLiquidity, "zdex: empty pool")
	g = ensureGauge(poolID, true)
	require(g.On, "zdex: gauge off")
	accrue(g)
	return sent, g
}

// Fund deposits OriginSend ugnot into the pool gauge as a lump (duration 0).
// Anyone EOA may incentivize. Does not call zdex swap or LP — PoolInfo only.
func Fund(cur realm, poolID string) {
	sent, g := takeFund(cur, poolID)
	_, _, _, totalLP, _ := zdex.PoolInfo(poolID)
	delta := amm.MulDiv(sent, scale, totalLP)
	require(delta > 0, "zdex: dust fund")
	g.Acc = add64(g.Acc, delta)
	g.TotalFunded = add64(g.TotalFunded, sent)
	chain.Emit("Fund", "pool", poolID, "amount", itoa(sent), "acc", itoa(g.Acc))
}

// FundProgram streams OriginSend ugnot over durationBlocks. Acc is not
// increased until accrue. durationBlocks >= 28800. A later FundProgram
// stacks leftover Remaining into the new window (does not overwrite).
func FundProgram(cur realm, poolID string, durationBlocks int64) {
	require(durationBlocks >= minProgramBlocks, "zdex: duration")
	sent, g := takeFund(cur, poolID)
	_, _, _, totalLP, _ := zdex.PoolInfo(poolID)
	require(amm.MulDiv(sent, scale, totalLP) > 0, "zdex: dust fund")
	pot := add64(g.Remaining, sent)
	rpb := pot / durationBlocks
	require(rpb > 0, "zdex: dust fund")
	now := height()
	g.EndH = add64(now, durationBlocks)
	g.RewardPerBlock = rpb
	g.Remaining = pot
	g.LastH = now
	g.TotalFunded = add64(g.TotalFunded, sent)
	chain.Emit("FundProgram", "pool", poolID, "amount", itoa(sent), "duration", itoa(durationBlocks), "rpb", itoa(rpb))
}

// accrue applies pending program emission to Acc. lastH becomes now, or endH
// if the window has closed.
func accrue(g *Gauge) {
	if g == nil || g.RewardPerBlock <= 0 {
		return
	}
	now := height()
	if now <= g.LastH {
		return
	}
	until := g.EndH
	if now < until {
		until = now
	}
	dt := until - g.LastH
	if dt > 0 && g.Remaining > 0 {
		pay := mul64(g.RewardPerBlock, dt)
		if pay > g.Remaining {
			pay = g.Remaining
		}
		if pay > 0 {
			_, _, _, totalLP, _ := zdex.PoolInfo(g.ID)
			delta := int64(0)
			if totalLP > 0 {
				delta = amm.MulDiv(pay, scale, totalLP)
			}
			if delta == 0 {
				if now >= g.EndH {
					g.LastH = until
				}
				return
			}
			g.Acc = add64(g.Acc, delta)
			g.Remaining = sub64(g.Remaining, pay)
		}
	}
	g.LastH = until
}

func pendingOf(poolID string, owner address) int64 {
	if g := tryGauge(poolID); g != nil {
		accrue(g)
	}
	st := tryStake(poolID, owner)
	if st == nil || st.LastLP <= 0 {
		return 0
	}
	acc := int64(0)
	if g := tryGauge(poolID); g != nil {
		acc = g.Acc
	}
	if acc <= st.LastAcc {
		return 0
	}
	live := zdex.PositionOf(poolID, owner)
	eligible := st.LastLP
	if live < eligible {
		eligible = live
	}
	if eligible <= 0 {
		return 0
	}
	return amm.MulDiv(eligible, acc-st.LastAcc, scale)
}

// Sync pays min(LastLP, live PositionOf) against Acc, then snapshots.
// RemoveLiquidity on v2 without Claim forfeits unclaimed gauge (insolvency).
func Sync(cur realm, poolID string) int64 {
	if g := tryGauge(poolID); g != nil {
		accrue(g)
	}
	caller := cur.Previous().Address()
	earned := pendingOf(poolID, caller)
	st := getOrCreateStake(poolID, caller)
	acc := int64(0)
	if g := tryGauge(poolID); g != nil {
		acc = g.Acc
	}
	st.LastLP = zdex.PositionOf(poolID, caller)
	st.LastAcc = acc
	if earned > 0 {
		if g := tryGauge(poolID); g != nil {
			g.TotalClaimed = add64(g.TotalClaimed, earned)
		}
		sendUgnot(0, cur, caller, earned)
	}
	chain.Emit("Sync", "pool", poolID, "to", caller.String(), "earned", itoa(earned))
	return earned
}

func ProposeAdmin(cur realm, next address) {
	mustOwner(cur)
	require(next.IsValid(), "zdex: invalid admin")
	pendingAdmin = next
	chain.Emit("ProposeAdmin", "to", next.String())
}

func AcceptAdmin(cur realm) {
	require(pendingAdmin.IsValid(), "zdex: no pending admin")
	require(cur.Previous().Address() == pendingAdmin, "zdex: not pending admin")
	admin = pendingAdmin
	var z address
	pendingAdmin = z
	chain.Emit("AcceptAdmin", "to", admin.String())
}

func PendingAdmin() address {
	return pendingAdmin
}

// SweepDust sends banker ugnot that is not Remaining and not Owed.
// Owner + paused only. Does not touch Claimable / Acc.
func SweepDust(cur realm, to address) int64 {
	mustOwner(cur)
	require(paused, "zdex: unpaused")
	require(to.IsValid(), "zdex: dest")
	reserved := int64(0)
	gauges.Iterate("", "", func(_ string, v any) bool {
		g := v.(*Gauge)
		accrue(g)
		reserved = add64(reserved, g.Remaining)
		return false
	})
	stakes.Iterate("", "", func(_ string, v any) bool {
		st := v.(*Stake)
		reserved = add64(reserved, pendingOf(st.PoolID, st.Owner))
		return false
	})
	rlm := cur
	require(rlm.IsCurrent(), "zdex: spoofed realm")
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bal := bk.GetCoins(rlm.Address()).AmountOf(nativeDenom)
	require(bal > reserved, "zdex: no dust")
	dust := sub64(bal, reserved)
	sendUgnot(0, cur, to, dust)
	chain.Emit("SweepDust", "to", to.String(), "amount", itoa(dust))
	return dust
}

func Claim(cur realm, poolID string) int64 {
	return Sync(cur, poolID)
}

func SetGauge(cur realm, poolID string, on bool) {
	mustOwner(cur)
	require(poolID != "", "zdex: pool")
	g := ensureGauge(poolID, on)
	g.On = on
	chain.Emit("SetGauge", "pool", poolID, "on", itoa(btoi(on)))
}

func SetPaused(cur realm, v bool) {
	mustOwner(cur)
	paused = v
	chain.Emit("Pause", "paused", itoa(btoi(v)))
}

func sendUgnot(_ int, rlm realm, to address, amount int64) {
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: nativeDenom, Amount: amount}})
}

package incentives

import "gno.land/p/nt/ufmt/v0"

func Version() string {
	return protoVersion
}

func DexPkg() string {
	return dexPkg
}

func Admin() address {
	return admin
}

func Paused() bool {
	return paused
}

// GaugeSnapshot is id;acc;totalFunded;on;paused;endH;rewardPerBlock;remaining
// (on/paused are 0/1).
func GaugeSnapshot(poolID string) string {
	acc, funded, on := int64(0), int64(0), int64(0)
	endH, rpb, rem := int64(0), int64(0), int64(0)
	if g := tryGauge(poolID); g != nil {
		accrue(g)
		acc = g.Acc
		funded = g.TotalFunded
		on = btoi(g.On)
		endH = g.EndH
		rpb = g.RewardPerBlock
		rem = g.Remaining
	}
	return ufmt.Sprintf("%s;%d;%d;%d;%d;%d;%d;%d", poolID, acc, funded, on, btoi(paused), endH, rpb, rem)
}

func GaugeList() string {
	out := ""
	gauges.Iterate("", "", func(k string, _ any) bool {
		if out != "" {
			out += "\n"
		}
		out += k
		return false
	})
	return out
}

func Claimable(poolID string, owner address) int64 {
	return pendingOf(poolID, owner)
}

package incentives

import (
	"chain/runtime"
	"math/overflow"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

const (
	nativeDenom      = "ugnot"
	scale            = int64(1_000_000_000)
	minFundUgnot     = int64(1_000_000)
	minLiquidity     = int64(1000)
	minProgramBlocks = int64(28800)
	dexPkg           = "gno.land/r/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/v2"
	protoVersion     = "4"
)

var (
	admin         address
	pendingAdmin  address
	paused        bool
	gauges        avl.Tree // poolID -> *Gauge
	stakes        avl.Tree // poolID/owner -> *Stake
)

type Gauge struct {
	ID             string
	Acc            int64
	TotalFunded    int64
	TotalClaimed   int64
	On             bool
	EndH           int64
	RewardPerBlock int64
	Remaining      int64
	LastH          int64
}

// LastLP/LastAcc are the sidecar checkpoint. Claimable and Sync both
// use stored LastLP, not live PositionOf, so a first Sync only snapshots.
type Stake struct {
	LastLP  int64
	LastAcc int64
	PoolID  string
	Owner   address
}

func init(cur realm) {
	admin = cur.Previous().Address()
}

func require(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

func mustOwner(cur realm) {
	if cur.Previous().Address() != admin {
		panic("zdex: admin only")
	}
}

func height() int64 {
	return runtime.ChainHeight()
}

func add64(a, b int64) int64 {
	s, ok := overflow.Add64(a, b)
	if !ok {
		panic("zdex: add overflow")
	}
	return s
}

func sub64(a, b int64) int64 {
	s, ok := overflow.Sub64(a, b)
	if !ok {
		panic("zdex: sub overflow")
	}
	return s
}

func mul64(a, b int64) int64 {
	p, ok := overflow.Mul64(a, b)
	if !ok {
		panic("zdex: mul overflow")
	}
	return p
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

func btoi(v bool) int64 {
	if v {
		return 1
	}
	return 0
}

func stakeKey(poolID string, owner address) string {
	return poolID + "/" + owner.String()
}

func tryGauge(poolID string) *Gauge {
	v := gauges.Get(poolID)
	if v == nil {
		return nil
	}
	return v.(*Gauge)
}

func tryStake(poolID string, owner address) *Stake {
	v := stakes.Get(stakeKey(poolID, owner))
	if v == nil {
		return nil
	}
	return v.(*Stake)
}

func getOrCreateStake(poolID string, owner address) *Stake {
	if st := tryStake(poolID, owner); st != nil {
		return st
	}
	st := &Stake{PoolID: poolID, Owner: owner}
	stakes.Set(stakeKey(poolID, owner), st)
	return st
}

// Fund creates the gauge on=true. SetGauge may create on=false.
func ensureGauge(poolID string, onIfNew bool) *Gauge {
	if g := tryGauge(poolID); g != nil {
		return g
	}
	g := &Gauge{ID: poolID, On: onIfNew}
	gauges.Set(poolID, g)
	return g
}

